export const QUEENBEE=Object.freeze({name:'QueenBee',special:'Bee Swarm Assault',kind:'beeSwarm',duration:2.7,range:900,color:'#ffdc65',glow:'rgba(255,190,45,.4)'});
const strikes=[.86,1.15,1.44,1.73,2.02,2.31];
export function createBeeSpecial(a){return {kind:QUEENBEE.kind,owner:a.id,facing:a.facing,originX:a.x,x:a.x,age:0,ttl:QUEENBEE.duration,duration:QUEENBEE.duration,active:true,delay:0,hitCount:0,strikeIndex:0};}
export function endBeeSpecial(g,a,s){s.active=false;s.ttl=0;if(a){a.vx=0;a.actionRemaining=0;g.setState(a,a.hp>0?'idle':'ko');}}
export function updateBeeSpecial(g,s,a,b){if(!a||!b){endBeeSpecial(g,a,s);return;}a.facing=s.facing;a.vx=0;if(s.ttl>1e-9){a.state='special';a.actionRemaining=Math.max(a.actionRemaining,s.ttl);}while(s.strikeIndex<strikes.length&&s.age>=strikes[s.strikeIndex]){const i=s.strikeIndex++;const dx=(b.x-s.originX)*s.facing;if(dx>=-35&&dx<=QUEENBEE.range&&b.y<185&&g.hit(a,b,8,s.kind,i===5?330:0,.16,b.x-s.facing))s.hitCount++;}if(s.ttl<=1e-9)endBeeSpecial(g,a,s);}
export function queenbeePose(f,s){const t=f.stateTime||0,p=f.attackProgress||0;let index=0;if(f.state==='ko')index=8;else if(f.state==='hurt')index=7;else if(f.state==='special')index=(s?.age??t)<.65?9:(s?.age??t)<2.45?10:11;else if(f.state==='punch')index=p>.22&&p<.78?4:0;else if(f.state==='kick')index=p>.22&&p<.78?5:0;else if(!f.grounded||f.state==='jump'||f.state==='fall')index=6;else if(f.state==='run'||f.state==='walk')index=[1,2,3,2][Math.floor(t*9)%4];return {key:'queenbee',index};}
export function drawBeeSpecial(ctx,s,g,ground){if(s.age<.65||s.age>2.55)return;const b=g.fighters.find(f=>f.id!==s.owner);if(!b)return;const fade=Math.min(1,(s.age-.65)*8,(2.55-s.age)*8);ctx.save();ctx.globalAlpha=Math.max(0,fade);for(let i=0;i<16;i++){const p=(s.age*1.9+i/16)%1;const x=s.originX+(b.x-s.originX)*p;const y=ground-110-b.y*p+Math.sin(i*2.4+s.age*10)*55;ctx.save();ctx.translate(x,y);ctx.scale(s.facing,1);ctx.strokeStyle='#ffe49b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-20,0);ctx.lineTo(-8,0);ctx.stroke();ctx.fillStyle='#ffca28';ctx.beginPath();ctx.ellipse(0,0,8,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#222';ctx.fillRect(-3,-4,3,8);ctx.fillRect(3,-4,2,8);ctx.fillStyle='#fff7df';ctx.beginPath();ctx.ellipse(-3,-6,5,3,-.5,0,Math.PI*2);ctx.ellipse(2,-6,5,3,.5,0,Math.PI*2);ctx.fill();ctx.restore();}ctx.restore();}
